parameters.command:
python3 << 'PYEOF'
import json

ANALYST_AGENT_ID = "b533cfee-5655-4cd9-9311-11c536d3c591"
WRITER_AGENT_ID  = "59837827-4760-4e6a-948f-50ac93cc23ff"
CONTEXT_SOP_UUID = "cc45b9b4-dbf6-47b3-40ac-08debc0cec5b"  # from nodeType suffix

# Load definitions from registry
def_end       = json.load(open("/tmp/def_end.json"))["Data"]["Node"]
def_switch    = json.load(open("/tmp/def_switch.json"))["Data"]["Node"]
def_merge     = json.load(open("/tmp/def_merge.json"))["Data"]["Node"]
def_decision  = json.load(open("/tmp/def_decision.json"))["Data"]["Node"]
def_script    = json.load(open("/tmp/def_script.json"))["Data"]["Node"]
def_agent     = json.load(open("/tmp/def_agent.json"))["Data"]["Node"]
def_ixp       = json.load(open("/tmp/def_ixp.json"))["Data"]["Node"]
def_fpf       = json.load(open("/tmp/def_fpf.json"))["Data"]["Node"]
def_ctx_sop   = json.load(open("/tmp/def_context_sop.json"))["Data"]["Node"]

# Read existing flow (has start, crmLookup1, erpLookup1, definitions for trigger+dataservice)
flow = json.load(open("BillingDisputeResolution.flow"))

# IxP model data
ixp_defaults = def_ixp.get("inputDefaults", {})
ixp_model_blob = ixp_defaults.get("model", {})
# Fix modelName if null
if not ixp_model_blob.get("modelName"):
    ixp_model_blob["modelName"] = ixp_model_blob.get("modelDisplayName", "invoices-billing")

# ---- NODES ----
new_nodes = [
    # 1. IxP extraction
    {
        "id": "extractInvoice",
        "type": def_ixp["nodeType"],
        "typeVersion": def_ixp["version"],
        "display": {"label": "Invoice Extraction (IxP)"},
        "inputs": {
            "model": ixp_model_blob,
            "modelName": ixp_defaults.get("modelName"),
            "projectName": ixp_defaults.get("projectName"),
            "versionTag": "",
            "folderKey": ixp_defaults.get("folderKey"),
            "folderName": ixp_defaults.get("folderName"),
            "fileRef": "=js:$vars.start.output.disputedInvoice",
            "pageRange": ""
        },
        "outputs": {
            "output": {"name": "output", "type": "object", "source": "=this", "var": "output"},
            "error":  {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 2. Normalize Data script
    {
        "id": "normalizeData",
        "type": "core.action.script",
        "typeVersion": "1.1",
        "display": {"label": "Normalize Data"},
        "inputs": {
            "language": "js",
            "script": """const fields = ($vars.extractInvoice.output &&
  $vars.extractInvoice.output.ExtractionResult &&
  $vars.extractInvoice.output.ExtractionResult.ResultsDocument &&
  $vars.extractInvoice.output.ExtractionResult.ResultsDocument.Fields) || [];
const normalized = fields.map(f => ({
  Id: f.FieldId,
  Name: f.FieldName,
  Value: (f.Values && f.Values.length > 0) ? f.Values[0] : null,
  Type: f.FieldType,
  IsMissing: f.IsMissing,
  Confidence: f.Confidence
}));
const rawInvoiceNum = (normalized.find(f => f.Name === 'InvoiceNumber' || f.Name === 'invoiceNumber') || {}).Value
  || $vars.start.output.webhookPayload.invoice.invoiceNumber || '';
const trimmed = rawInvoiceNum.trim().toUpperCase();
const invoiceNumber = trimmed.startsWith('MCS-') ? trimmed : ('MCS-' + trimmed);
return { normalizedFields: normalized, invoiceNumber: invoiceNumber };"""
        },
        "outputs": {
            "output": {"type": "object", "source": "=this", "var": "output"},
            "error":  {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 3. Merge after parallel CRM+ERP
    {
        "id": "mergeAfterLookup",
        "type": "core.logic.merge",
        "typeVersion": "1.0",
        "display": {"label": "Merge Lookups"},
        "inputs": {}
    },
    # 4. Discrepancy Detection script
    {
        "id": "detectDiscrepancies",
        "type": "core.action.script",
        "typeVersion": "1.1",
        "display": {"label": "Discrepancy Detection"},
        "inputs": {
            "language": "js",
            "script": """const disputedItems = ($vars.start.output.webhookPayload &&
  $vars.start.output.webhookPayload.dispute &&
  $vars.start.output.webhookPayload.dispute.disputedLineItems) || [];
const erpRecords = ($vars.erpLookup1.output && $vars.erpLookup1.output.value) || [];
const mismatches = [];
let totalOvercharge = 0;
let totalUndercharge = 0;
for (const item of disputedItems) {
  const erpRow = erpRecords.find(r => String(r.lineNumber) === String(item.lineNumber));
  if (!erpRow) {
    mismatches.push({ lineNumber: item.lineNumber, issue: 'not_in_contract', disputedAmount: item.amount, contractAmount: null, delta: 0 });
    continue;
  }
  const disputedAmt = parseFloat(item.amount) || 0;
  const contractAmt = parseFloat(erpRow.amount || erpRow.contractAmount || erpRow.unitPrice * erpRow.quantity) || 0;
  const delta = disputedAmt - contractAmt;
  if (Math.abs(delta) > 0.01) {
    mismatches.push({ lineNumber: item.lineNumber, description: item.description, disputedAmount: disputedAmt, contractAmount: contractAmt, delta: delta });
    if (delta > 0) totalOvercharge += delta;
    else totalUndercharge += Math.abs(delta);
  }
}
return { mismatches: mismatches, totalOvercharge: totalOvercharge, totalUndercharge: totalUndercharge };"""
        },
        "outputs": {
            "output": {"type": "object", "source": "=this", "var": "output"},
            "error":  {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 5. Dispute Analyst Agent
    {
        "id": "disputeAnalyst",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.3",
        "display": {"label": "Dispute Analyst Agent"},
        "inputs": {
            "systemPrompt": "Billing dispute analyst.",
            "userPrompt": "Analyze the billing dispute and return a determination.",
            "source": ANALYST_AGENT_ID,
            "agentInputVariables": [
                {"id": "normalizeData__output__invoiceNumber",   "type": "string", "binding": "=$vars.normalizeData.output.invoiceNumber"},
                {"id": "normalizeData__output__normalizedFields","type": "array",  "binding": "=$vars.normalizeData.output.normalizedFields"},
                {"id": "crmLookup1__output__value",              "type": "array",  "binding": "=$vars.crmLookup1.output.value"},
                {"id": "erpLookup1__output__value",              "type": "array",  "binding": "=$vars.erpLookup1.output.value"},
                {"id": "detectDiscrepancies__output__mismatches",     "type": "array",  "binding": "=$vars.detectDiscrepancies.output.mismatches"},
                {"id": "detectDiscrepancies__output__totalOvercharge", "type": "number", "binding": "=$vars.detectDiscrepancies.output.totalOvercharge"},
                {"id": "detectDiscrepancies__output__totalUndercharge","type": "number", "binding": "=$vars.detectDiscrepancies.output.totalUndercharge"},
                {"id": "start__output__webhookPayload",          "type": "object", "binding": "=$vars.start.output.webhookPayload"}
            ],
            "agentOutputVariables": [
                {"id": "determination",          "type": "string"},
                {"id": "recommendedAction",      "type": "string"},
                {"id": "autoResolutionEligible", "type": "boolean"},
                {"id": "creditAmount",           "type": "number"},
                {"id": "confidence",             "type": "number"},
                {"id": "rationale",              "type": "string"}
            ]
        },
        "outputs": {
            "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 6. Context SOP resource node for analyst agent
    {
        "id": "sopContextNode",
        "type": "uipath.agent.resource.context.index.billing-dispute-sop-index.cc45b9b4-dbf6-47b3-40ac-08debc0cec5b",
        "typeVersion": "1.0.0",
        "display": {"label": "Billing Dispute SOP Index"},
        "inputs": {"source": CONTEXT_SOP_UUID}
    },
    # 7. Switch on recommendedAction
    {
        "id": "switchOnAction",
        "type": "core.logic.switch",
        "typeVersion": "1.1",
        "display": {"label": "Switch on Recommended Action"},
        "inputs": {
            "cases": [
                {"id": "escalate",    "label": "Escalate to Manager", "expression": "$vars.disputeAnalyst.output.recommendedAction === 'escalate_to_manager'"},
                {"id": "auto_resolve","label": "Auto Resolve",        "expression": "$vars.disputeAnalyst.output.recommendedAction === 'auto_resolve'"},
                {"id": "reject",      "label": "Reject",              "expression": "$vars.disputeAnalyst.output.recommendedAction === 'reject'"}
            ]
        }
    },
    # 8. Manager Approval Decision
    {
        "id": "managerApproval",
        "type": "core.logic.decision",
        "typeVersion": "1.2",
