        "type": "uipath.core.api-workflow.07d45a91-9413-4dad-82ff-28306c2d85ea",
        "typeVersion": "1.0.0",
        "display": {"label": "Financial Posting"},
        "inputs": {},
        "outputs": {
            "error": {"type": "object", "description": "Error information if the API workflow fails", "source": "=Error", "var": "error"}
        }
    },
    # 11. Resolution Writer Agent
    {
        "id": "resolutionWriter",
        "type": "uipath.agent.autonomous",
        "typeVersion": "1.3",
        "display": {"label": "Resolution Writer Agent"},
        "inputs": {
            "systemPrompt": "Resolution email writer.",
            "userPrompt": "Draft the customer-facing resolution email.",
            "source": WRITER_AGENT_ID,
            "agentInputVariables": [
                {"id": "normalizeData__output__invoiceNumber", "type": "string", "binding": "=$vars.normalizeData.output.invoiceNumber"},
                {"id": "disputeAnalyst__output__creditAmount", "type": "number", "binding": "=$vars.disputeAnalyst.output.creditAmount"},
                {"id": "disputeAnalyst__output__determination", "type": "string", "binding": "=$vars.disputeAnalyst.output.determination"},
                {"id": "disputeAnalyst__output__rationale", "type": "string", "binding": "=$vars.disputeAnalyst.output.rationale"},
                {"id": "start__output__webhookPayload", "type": "object", "binding": "=$vars.start.output.webhookPayload"}
            ],
            "agentOutputVariables": [
                {"id": "subject", "type": "string"},
                {"id": "body",    "type": "string"}
            ]
        },
        "outputs": {
            "error": {"type": "object", "description": "Error information if the node fails", "source": "=Error", "var": "error"}
        }
    },
    # 12. Return Resolution end node
    {
