            "resolutionEmailBody":{"source": "'No resolution email was drafted — dispute rejected.'"}
        }
    }
]

# ---- EDGES ----
edges = [
    # start → extractInvoice
    {"id": "edge_start_output_extractInvoice_input", "sourceNodeId": "start", "sourcePort": "output", "targetNodeId": "extractInvoice", "targetPort": "input"},
    # extractInvoice → normalizeData
    {"id": "edge_extractInvoice_success_normalizeData_input", "sourceNodeId": "extractInvoice", "sourcePort": "success", "targetNodeId": "normalizeData", "targetPort": "input"},
    # normalizeData → crmLookup1 (parallel)
    {"id": "edge_normalizeData_output_crmLookup1_input", "sourceNodeId": "normalizeData", "sourcePort": "output", "targetNodeId": "crmLookup1", "targetPort": "input"},
    # normalizeData → erpLookup1 (parallel)
    {"id": "edge_normalizeData_output_erpLookup1_input", "sourceNodeId": "normalizeData", "sourcePort": "output", "targetNodeId": "erpLookup1", "targetPort": "input"},
    # crmLookup1 → merge
    {"id": "edge_crmLookup1_output_mergeAfterLookup_input", "sourceNodeId": "crmLookup1", "sourcePort": "output", "targetNodeId": "mergeAfterLookup", "targetPort": "input"},
    # erpLookup1 → merge
    {"id": "edge_erpLookup1_output_mergeAfterLookup_input", "sourceNodeId": "erpLookup1", "sourcePort": "output", "targetNodeId": "mergeAfterLookup", "targetPort": "input"},
    # merge → detectDiscrepancies
    {"id": "edge_mergeAfterLookup_output_detectDiscrepancies_input", "sourceNodeId": "mergeAfterLookup", "sourcePort": "output", "targetNodeId": "detectDiscrepancies", "targetPort": "input"},
    # detectDiscrepancies → disputeAnalyst
    {"id": "edge_detectDiscrepancies_output_disputeAnalyst_input", "sourceNodeId": "detectDiscrepancies", "sourcePort": "output", "targetNodeId": "disputeAnalyst", "targetPort": "input"},
    # disputeAnalyst context → sopContextNode
    {"id": "edge_disputeAnalyst_context_sopContextNode_input", "sourceNodeId": "disputeAnalyst", "sourcePort": "context", "targetNodeId": "sopContextNode", "targetPort": "input"},
    # disputeAnalyst → switchOnAction
    {"id": "edge_disputeAnalyst_success_switchOnAction_input", "sourceNodeId": "disputeAnalyst", "sourcePort": "success", "targetNodeId": "switchOnAction", "targetPort": "input"},
    # switch case-escalate → managerApproval
    {"id": "edge_switchOnAction_escalate_managerApproval_input", "sourceNodeId": "switchOnAction", "sourcePort": "case-escalate", "targetNodeId": "managerApproval", "targetPort": "input"},
    # switch case-auto_resolve → logCreditAmount
    {"id": "edge_switchOnAction_auto_resolve_logCreditAmount_input", "sourceNodeId": "switchOnAction", "sourcePort": "case-auto_resolve", "targetNodeId": "logCreditAmount", "targetPort": "input"},
    # switch case-reject → endRejection
    {"id": "edge_switchOnAction_reject_endRejection_input", "sourceNodeId": "switchOnAction", "sourcePort": "case-reject", "targetNodeId": "endRejection", "targetPort": "input"},
    # managerApproval false (Approved) → financialPosting
    {"id": "edge_managerApproval_false_financialPosting_input", "sourceNodeId": "managerApproval", "sourcePort": "false", "targetNodeId": "financialPosting", "targetPort": "input"},
    # managerApproval true (Rejected) → endManagerRejection
    {"id": "edge_managerApproval_true_endManagerRejection_input", "sourceNodeId": "managerApproval", "sourcePort": "true", "targetNodeId": "endManagerRejection", "targetPort": "input"},
    # logCreditAmount → financialPosting
    {"id": "edge_logCreditAmount_output_financialPosting_input", "sourceNodeId": "logCreditAmount", "sourcePort": "output", "targetNodeId": "financialPosting", "targetPort": "input"},
    # financialPosting → resolutionWriter
    {"id": "edge_financialPosting_output_resolutionWriter_input", "sourceNodeId": "financialPosting", "sourcePort": "output", "targetNodeId": "resolutionWriter", "targetPort": "input"},
    # resolutionWriter → endReturnResolution
    {"id": "edge_resolutionWriter_success_endReturnResolution_input", "sourceNodeId": "resolutionWriter", "sourcePort": "success", "targetNodeId": "endReturnResolution", "targetPort": "input"}
]

# ---- DEFINITIONS ----
# existing definitions already have: core.trigger.manual, uipath.connector.uipath-uipath-dataservice.query-entity-records
new_defs = [
    def_ixp,
    def_script,
    def_merge,
    def_decision,
    def_switch,
    def_agent,
    def_fpf,
    def_ctx_sop,
    def_end
]

# ---- VARIABLES ----
# Globals: in variables
globals_vars = [
    {"id": "disputedInvoice", "direction": "in", "type": "file",   "triggerNodeId": "start"},
    {"id": "webhookPayload",  "direction": "in", "type": "object", "triggerNodeId": "start"},
    # out variables
    {"id": "determination",       "direction": "out", "type": "string"},
    {"id": "recommendedAction",   "direction": "out", "type": "string"},
    {"id": "creditAmount",        "direction": "out", "type": "number"},
    {"id": "rationale",           "direction": "out", "type": "string"},
    {"id": "resolutionEmailBody", "direction": "out", "type": "string"}
]

# nodes output variable entries
new_node_vars = [
    {"id": "extractInvoice.output", "type": "object", "binding": {"nodeId": "extractInvoice", "outputId": "output"}},
    {"id": "normalizeData.output",  "type": "object", "binding": {"nodeId": "normalizeData",  "outputId": "output"}},
    {"id": "mergeAfterLookup.output","type": "object","binding": {"nodeId": "mergeAfterLookup","outputId": "output"}},
    {"id": "detectDiscrepancies.output","type": "object","binding": {"nodeId": "detectDiscrepancies","outputId": "output"}},
    {"id": "disputeAnalyst.output", "type": "object", "binding": {"nodeId": "disputeAnalyst","outputId": "output"}},
    {"id": "disputeAnalyst.error",  "type": "object", "binding": {"nodeId": "disputeAnalyst","outputId": "error"}},
    {"id": "logCreditAmount.output","type": "object", "binding": {"nodeId": "logCreditAmount","outputId": "output"}},
    {"id": "financialPosting.output","type": "object","binding": {"nodeId": "financialPosting","outputId": "output"}},
    {"id": "resolutionWriter.output","type": "object","binding": {"nodeId": "resolutionWriter","outputId": "output"}},
    {"id": "resolutionWriter.error", "type": "object","binding": {"nodeId": "resolutionWriter","outputId": "error"}}
]

# ---- BINDINGS for FinancialPostingFunction ----
fpf_bindings = [
    {
        "id": "bFpfName",
        "name": "name",
        "type": "string",
        "resource": "process",
