new_layout = {
    "extractInvoice":      {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "normalizeData":       {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "mergeAfterLookup":    {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "detectDiscrepancies": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "disputeAnalyst":      {"position": {"x": 0, "y": 0}, "size": {"width": 288, "height": 96}, "collapsed": False},
    "sopContextNode":      {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "switchOnAction":      {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "managerApproval":     {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "logCreditAmount":     {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "financialPosting":    {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "resolutionWriter":    {"position": {"x": 0, "y": 0}, "size": {"width": 288, "height": 96}, "collapsed": False},
    "endReturnResolution": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "endManagerRejection": {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False},
    "endRejection":        {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
}

# ---- ASSEMBLE ----
# Add new nodes to existing nodes list
flow["nodes"] = flow["nodes"] + new_nodes

# Set edges
flow["edges"] = edges

# Add new definitions (avoid duplicates)
existing_types = {d.get("nodeType") for d in flow["definitions"]}
for nd in new_defs:
    if nd.get("nodeType") not in existing_types:
        flow["definitions"].append(nd)

# Set globals
if "variables" not in flow:
    flow["variables"] = {}
flow["variables"]["globals"] = globals_vars

# Extend node vars
existing_node_var_ids = {v["id"] for v in flow["variables"].get("nodes", [])}
for nv in new_node_vars:
    if nv["id"] not in existing_node_var_ids:
        flow["variables"]["nodes"].append(nv)

# Extend bindings
if "bindings" not in flow:
    flow["bindings"] = []
existing_binding_ids = {b["id"] for b in flow["bindings"]}
for b in fpf_bindings:
    if b["id"] not in existing_binding_ids:
        flow["bindings"].append(b)

# Extend layout
for k, v in new_layout.items():
    if k not in flow["layout"]["nodes"]:
        flow["layout"]["nodes"][k] = v

# Write back
with open("BillingDisputeResolution.flow", "w") as f:
    json.dump(flow, f, indent=2)

print("Flow written successfully")
